/**
 * 대구역 역 내 도면 데이터.
 *
 * 프로토타입(프로토타입_수정본.html)의 지도 데이터를 그대로 옮긴 것이다.
 * 도면은 정적 데이터라 프론트가 소유하고, 경로 API 는 단계별 좌표만 주면 된다.
 *
 * 전체 연결도(floor "0")는 단계 번호를 표시하지 않으므로 제외했다. (67KB 절감)
 * 좌표계는 2000x2000 이다.
 *
 * TODO: 실제 도면이 확정되면 이 파일만 교체한다.
 *       사용자 앱도 같은 지도를 쓰게 되면 shared 로 옮기는 것을 검토한다.
 */

/** 도면 좌표계 한 변의 길이 */
export const STATION_MAP_SIZE = 2000

export interface StationMapView {
  /** 뷰 식별자 */
  key: string
  /** 해당 층 */
  floor: string
  /** 층 탭에 표시할 이름 */
  label: string
  /** 뷰 중심 x */
  cx: number
  /** 뷰 중심 y */
  cy: number
  /** 뷰 반경. viewBox 는 (cx-half, cy-half, half*2, half*2) 가 된다. */
  half: number
}

/** 층·구역별 보기 설정 */
